function twDetails(r){return `<section class="strict-details"><h4>固定格式｜${r.confirmedTrade?'已核實條件':'條件式觀察，非確認交易訊號'}</h4><ol class="fixed-fields">${twOutputFields(r).map(([label,value])=>`<li><b>${escapeHtml(label)}</b><span>${escapeHtml(value)}</span></li>`).join('')}</ol><p>第一目標回補50%；其餘依下一交易日才生效的移動停損管理。停損只可收緊，禁止攤平或擴大原始停損。</p></section>`;}
function diagnosticCard(r){return `<article class="panel signal-card diagnostic-card" data-stock-key="${escapeHtml(stockKey(r))}"><details><summary><div class="signal-top"><div><h3>${escapeHtml(r.name||r.code)}<span class="symbol">${escapeHtml(r.code)} · TWD</span></h3><p class="signal-stage">備查診斷｜${escapeHtml(r.patternName||'關鍵資料／型態不足')}</p></div>${badge('未列推薦','amber')}</div><p class="signal-reason">${escapeHtml(r.sourceCrossCheck?.status!=='VERIFIED'?'Yahoo奇摩與對應交易所未完成交叉核實，不提供進場建議。':r.statusReason||'條件未達標，不提供進場建議。')}</p><div class="signal-metrics">${metric('官方最新收盤',price(r.close))}${metric('全日成交股數',format(r.volume,0))}${metric('前20日均量（股）',format(r.averageVolume20,0))}${metric('量比',format(r.volumeRatio))}${metric('ADX14',format(r.adx14))}${metric('-DI／+DI',`${format(r.minusDI14)}／${format(r.plusDI14)}`)}${metric('MA240',price(r.ma240))}${metric('60交易日報酬',percent(finite(r.return60)?r.return60*100:null))}</div><p class="diagnostic-time">${escapeHtml(r.dataTimeTaipei||r.dataDate||'日期待確認')}（台灣，完整收盤日K；時間為收盤截止）</p><div class="signal-expand">展開未達條件與來源狀態<span>⌄</span></div></summary><div class="signal-detail"><p>${escapeHtml(r.statusReason||'資料不足，不補造數值')}</p><p>ADX：${escapeHtml(r.adxMethod?.method||'歷史不足，無有效ADX')}<br>期間：${escapeHtml(r.adxMethod?.calculationStart||'—')} ～ ${escapeHtml(r.adxMethod?.cutoff||'—')}<br>正式推薦所需來源：Yahoo奇摩＋對應TWSE／TPEx；目前 ${escapeHtml(r.sourceCrossCheck?.status||'待核實')}。</p><p>這是資料／技術條件的備查診斷，不是觀察進場名單。技術品質與券商資格分開，券源仍待確認。</p></div></details></article>`;}
